Rules.InvariantScript:
If(
    !IsBlank(ThisItem.Descricao),
    "Apontamento: " & ThisItem.Descricao & " | "
) & If(
    !IsBlank(ThisItem.Descricao),
    ThisItem.Descricao & " | "
) & If(
    !IsBlank(ThisItem.Mapa_grade),
    ThisItem.Mapa_grade & " | "
) & If(
    !IsBlank(ThisItem.Chamado),
    "Chamado: " & ThisItem.Chamado & " | "
) & If(
    !IsBlank(ThisItem.Latitude),
    "Latitude: " & ThisItem.Latitude & " | "
) & If(
    !IsBlank(ThisItem.Longitude),
    "Longitude: " & ThisItem.Longitude & " | "
) & If(
    !IsBlank(ThisItem.Quant),
    "Quantidade: " & ThisItem.Quant & " | "
) & If(
    !IsBlank(ThisItem.Status),
    "Status: " & ThisItem.Status & " | "
) & If(
    !IsBlank(ThisItem.Identificação),
    "Identificação: " & ThisItem.Identificação
)
